}

solutionCodeJson.code:
// Bài 8.2 — LIKE: % = bất kỳ, _ = một ký tự, khớp cả chuỗi, không phân biệt hoa thường
function likeToRegExp(pattern) {
  let body = '';
  for (const ch of pattern) {
    if (ch === '%') body += '.*';
    else if (ch === '_') body += '.';
    else body += ch.replace(/[.*+?^${}()|[\]\\/]/g, '\\$&');   // mọi ký tự khác là chính nó
  }
  return new RegExp('^' + body + '$', 'is');
}

