  return rows.sort((a, b) => a[k] - b[k]);
}

solutionCodeJson.code:
// Bài 8.2 — so từng khoá tới khi khác; NULL nhỏ nhất (đầu khi ASC, cuối khi DESC)
function orderBy(rows, keys) {
  const norm = (v) => (v === undefined ? null : v);
  const cmp = (a, b) => {
    a = norm(a); b = norm(b);
    if (a === b) return 0;
    if (a === null) return -1;
    if (b === null) return 1;
    return a < b ? -1 : 1;
  };
  return rows.toSorted((x, y) => {                          // toSorted: ổn định và không sửa mảng gốc
    for (const [k, dir] of keys) {
      const r = cmp(x[k], y[k]);
      if (r !== 0) return dir === 'desc' ? -r : r;
    }
    return 0;
  });
}

